package vn.covie.reputation.persistence;
import jakarta.persistence.LockModeType; import java.time.Instant; import java.util.Optional; import java.util.UUID; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Lock; import org.springframework.data.jpa.repository.Modifying; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import vn.covie.reputation.model.MerchantReputationStatsEntity;
public interface MerchantReputationStatsRepository extends JpaRepository<MerchantReputationStatsEntity, UUID> { @Modifying(flushAutomatically=true) @Query(value="insert into merchant_reputation_stats(merchant_profile_id,updated_at) values (:merchantId,:now) on conflict (merchant_profile_id) do nothing",nativeQuery=true) int ensureEmpty(@Param("merchantId") UUID merchantId,@Param("now") Instant now); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select s from MerchantReputationStatsEntity s where s.merchantProfileId=:merchantId") Optional<MerchantReputationStatsEntity> findForUpdate(@Param("merchantId") UUID merchantId); }
